<?php require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/auth.php'; require_login(); $id=(int)($_GET['id']??0); $stmt=$mysqli->prepare('SELECT b.*,s.slot_number FROM bookings b JOIN slots s ON s.id=b.slot_id WHERE b.id=? AND b.user_id=?');$uid=$_SESSION['user']['id'];$stmt->bind_param('ii',$id,$uid);$stmt->execute();$b=$stmt->get_result()->fetch_assoc();if(!$b){flash('error','Booking not found.');header('Location: dashboard.php');exit;}$page_title='Booking pass';require __DIR__.'/../includes/header.php';$qr='https://api.qrserver.com/v1/create-qr-code/?size=220x220&data='.rawurlencode($b['booking_code']); ?>
<div class="row justify-content-center"><div class="col-md-7"><div class="card shadow-sm border-0 text-center"><div class="card-body p-4"><span class="badge text-bg-primary mb-2"><?=e($b['status'])?></span><h2><?=e($b['booking_code'])?></h2><p class="text-muted">Slot <?=e($b['slot_number'])?> · show this code at entry and exit.</p><?php if($b['status']!=='pending_payment'): ?><img class="qr my-3" src="<?=$qr?>" alt="QR pass"><p class="small text-muted">QR data: <?=e($b['booking_code'])?></p><?php else:?><a class="btn btn-primary" href="payment.php?id=<?=$id?>">Complete payment</a><?php endif;?></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
